custom_css:
/* 🐨字体导入 */
@import url("https://fontsapi.zeoseven.com/200/main/result.css");

/* 🐸全局变量 */
  :root {
    /* 字体 */
    --font1: "cjkFonts 全瀨體";
    --mainFontFamily: var(--font1);

    /* 颜色 */
    --color1: rgba(0, 0, 0, 1);
    --color2: rgba(255, 255, 255, 1);
    --color3: rgba(109, 70, 44, 1);
    --color4: rgba(109, 70, 44, 0.5);
    --color5: rgba(250, 225, 159, 1);
    --color6: rgba(253, 241, 220, 1);
    --color7: rgba(157, 37, 22, 1);
    --color8: rgba(255, 247, 238, 1);
    --color9: rgba(194, 163, 113, 1);
    --color10: rgba(141, 71, 38, 1);
    --color11: rgba(255, 246, 156, 1);
    --color12: rgba(157, 37, 22, 0.5);
    --black30a: transparent;

/* 适配 */
    /* 🐦顶栏适配 */
    --顶栏背景图宽度: 100%;
    --顶栏背景图高度: 500px;
    --顶栏背景图上下: 0px;
    --顶栏背景图左右: 0px;
    --顶栏图标大小: 25px;
    --顶栏图标宽度: 25px;
    --顶栏图标高度: 25px;
    --顶栏图标尺寸: 22px;
    --悬停和选中顶栏图标宽度: 24px;
    --悬停和选中顶栏图标高度: 24px;
    --悬停和选中顶栏图标下移: 1px;

    /* 🐤气泡适配 */
    --气泡与底部距离: 120px;
    --消息顶部留空: 90px;
    --气泡最小高度: 0px;
    --消息留空: 90px;
    --消息底部留空: 0px;
    --渐隐程度: 200px;
    --气泡上边距: 0px;
    --气泡右边距: 10px;
    --气泡下边距: 60px;
    --气泡左边距: 10px;
    --气泡上边框: 60px;
    --气泡右边框: 10px;
    --气泡下边框: 60px;
    --气泡左边框: 10px;
    --格纹大小: 250px;

    /* 装饰适配 */
    --顶部装饰宽度: 100%;
    --顶部装饰高度: 100px;
    --顶部装饰上下: 0px;
    --顶部装饰左右: 0px;
    --底部装饰宽度: 100px;
    --底部装饰高度: 150px;
    --底部装饰上下: -48px;
    --底部装饰左右: 27px;
    --尾部文字大小: 10px;
    --尾部文字上下: 0px;
    --尾部文字左右: 0px;
    --横线宽度: 85%;
    --横线上下: 0px;
    --横线左右: 0px;

    /* 🌵头像适配 */
    --头像区域整体上下: -5px;
    --头像区域整体左右: 50%;
    --头像上下: -50px;
    --头像左右: 0px;
    --头像宽度: 82px;
    --头像高度: 82px;
    --头像图片位置: 50% 50%;
    --摸摸头宽度: 150px;
    --摸摸头高度: 120px;
    --摸摸头上下: 0px;
    --摸摸头左右: 0px;
    --头像框宽度: 370px;
    --头像框高度: 400px;
    --头像框上下: -130px;
    --头像框左右: 50%;
    --信息字体大小: 10px;
    --信息上下: 0px;
    --信息左右: 0px;
    --信息宽度: 100px;

    /* 楼层适配 */
    --楼层上下: 21px;
    --楼层左右: -124px;
    --楼层字体大小: 10px;
    --楼层宽度: 80px;

    /* 时间适配 */
    --时间上下: -35px;
    --时间左右: 93px;
    --时间字体大小: 9px;
    --时间宽度:70px;

    /* Token适配 */
    --Token上下: 4px;
    --Token左右: 107px;
    --Token字体大小: 7px;
    --Token宽度: 50px;

    /* 🕊️名字适配 */
    --名字上下: 11px;
    --名字左右: 155px;
    --名字字体大小: 11px;
    --名字宽度: 180px;

    /* 时间戳适配 */
    --时间戳上下: 78px;
    --时间戳左右: 80px;
    --时间戳字体大小: 7px;
    --时间戳宽度:180px;

    /* 小幽灵适配 */
    --小幽灵宽度: 80px;
    --小幽灵高度: 100px;
    --小幽灵上下: -98px;
    --小幽灵左右: 20px;

    /* 🌿思维链适配 */
    --思维链上下: 23px;
    --思维链左右: 7%;
    --思维链宽度: 200px;
    --思维链高度: 100px;         
    --思维链文字大小: 9px;
    --思维链文字: "你也想吃草莓布丁可可三明治吗？";

    /* ☘️按钮适配 */
    --按钮组上下: 43px;
    --按钮组左右: 25px;
    --按钮间距: 18px;
    --按钮装饰宽度: 30px;
    --按钮装饰高度: 30px;
    --按钮装饰上下: -5px;
    --按钮装饰左右: -7.5px;
    --三个点宽度: 15px;
    --三个点高度: 15px;
    --小铅笔宽度: 15px;
    --小铅笔高度: 15px;
    --消息操作按钮组上下: 0px;
    --消息操作按钮组左右: 0px;
    --编辑时的按钮左右: 20px;
    --编辑时的按钮上下: 73px;
    --思维链按钮组上下: 77px;
    --思维链按钮组左右: 20px;
    --思维链按钮宽度:20px;
    --思维链按钮高度:20px;

    /* 🍹页码区适配 */
    --左箭头上下: 10px;
    --左箭头左右: 20px;
    --左箭头宽度: 60px;
    --左箭头高度: 55px;
    --右箭头上下: -25px;
    --右箭头左右: 5px;
    --右箭头宽度: 50px;
    --右箭头高度: 60px;
    --页码上下: 0px;
    --页码左右: -2px;
    --页码大小: 13px;

    /* 🐣文字效果适配 */
    --文字区域上边距: 100px;
    --文字区域左边距: 10px;
    --文字区域右边距: 7px;
    --文字区域下边距: 10px;
    --正文上边距: 0px;
    --正文右边距: 0px;
    --正文下边距: 0px;
    --正文左边距: 0px;

    /* 🎋底栏适配 */
    --底栏上边距: 6px;
    --底栏下边距: 5px;
    --底栏左边距: 5px;
    --底栏右边距: 5px;
    --底栏宽度: 100%;
    --底栏底部留空: 0px;
    --底栏图标间隔:05px;
    --底栏图标大小: 20px;
    --底栏整体图标宽度: 20px;
    --底栏整体图标高度: 20px;
    --底栏图片大小: 400px;
    --QR助手宽度: 20px;
    --QR助手高度: 20px;
    --停止图标宽度: 20px;
    --停止图标高度: 20px;
    /* 输入框适配 */
    --输入框上留空: 0px;
    --输入框下留空: 0px;
    --输入框左留空: 5px;
    --输入框右留空: 5px;
    --输入框文字: "•ㅅ•草莓茉莉素StrawberryJasmine";
    --输入框文字大小: 8px;
    --输入框文字左右: 52%;
    --底栏装饰上下: -42px;
    --底栏装饰左右: -10px;
    --底栏装饰高度: 50px;
    --底栏装饰宽度: 110%;
  }

  /* 🐧字体使用 */
  body {
    font-family: var(--font1);
    font-weight: normal;
  }

  /* 🐦顶栏 */
  /* 去顶栏阴影 */
  #top-bar {
    box-shadow: none !important;
  }
  /* 顶栏背景 */
  #top-settings-holder {
    background-color: var(--SmartThemeQuoteColor);
    box-shadow:
      0 0 10px var(--SmartThemeBotMesBlurTintColor),
      0 0 25px var(--SmartThemeBotMesBlurTintColor),
      0 8px 40px var(--SmartThemeBotMesBlurTintColor),
      0 4px 5px rgba(0, 0, 0, 0.2);
  }

/* 顶栏透明 */
body.no-blur #top-bar {
    background-color: transparent !important;
}
  #top-settings-holder,
  #top-settings-holder .drawer,
  #top-settings-holder .drawer-toggle,
  #top-settings-holder .drawer-header,
  #top-bar {
      background-color: transparent !important; 
      background: transparent !important;
      box-shadow: none !important;
      border: none !important;
      backdrop-filter: none !important; 
      -webkit-backdrop-filter: none !important;
  }

  /* 允许溢出 */
  #top-settings-holder {
      position: relative; 
      overflow: visible !important; 
  }

  /* 顶栏背景 */
  #top-settings-holder::before {
      content: "";
      position: absolute;
      width: var(--顶栏背景图宽度);
      height: var(--顶栏背景图高度);
      background-image: url("https://iili.io/qYbu48N.png");
      background-size: 100% auto; 
      background-repeat: no-repeat;
      background-position: center top; 
      top: var(--顶栏背景图上下); 
      left: var(--顶栏背景图左右);
      pointer-events: none; 
      z-index: -1 !important;
  }

  /* 图标居中 */
  #top-settings-holder > div {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
  }

  /* 原始顶栏图标大小 */
  #top-settings-holder .drawer-icon::before {
    font-size: var(--顶栏图标大小);
  }

  /* 隐藏顶栏图标 */
  #top-settings-holder > div > :first-child {
    background-color: transparent !important;
    box-shadow: none !important;
    border: none !important;
    /* 图标 */
    background-size: var(--顶栏图标尺寸) auto !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
    /* 框大小 */
    width: var(--顶栏图标宽度) !important;
    height: var(--顶栏图标高度) !important;
  }
  #top-settings-holder .drawer-icon::before,
  #top-settings-holder .drawer-icon:hover::before,
  #top-settings-holder .drawer-icon:not(.closedIcon)::before {
    opacity: 0 !important;
    visibility: hidden !important;
  }

  /* 顶栏图标替换 */
  #top-settings-holder > .drawer:nth-of-type(1) .drawer-toggle { background-image: url("https://iili.io/qao6Jbs.png") !important; }
  #top-settings-holder > .drawer:nth-of-type(2) .drawer-toggle { background-image: url("https://iili.io/qaznVyB.png") !important; }
  #top-settings-holder > .drawer:nth-of-type(3) .drawer-toggle { background-image: url('https://iili.io/qao6Jbs.png') !important; }
  #top-settings-holder > .drawer:nth-of-type(4) .drawer-toggle { background-image: url('https://iili.io/qaznVyB.png') !important; }
  #top-settings-holder > .drawer:nth-of-type(5) .drawer-toggle { background-image: url('https://iili.io/qao6Jbs.png') !important; }
  #top-settings-holder > .drawer:nth-of-type(6) .drawer-toggle { background-image: url('https://iili.io/qaznVyB.png') !important; }
  #top-settings-holder > .drawer:nth-of-type(7) .drawer-toggle { background-image: url('https://iili.io/qao6Jbs.png') !important; }
  #top-settings-holder > .drawer:nth-of-type(8) .drawer-toggle { background-image: url('https://iili.io/qaznVyB.png') !important; }
  #top-settings-holder > .drawer:nth-of-type(9) .drawer-toggle { background-image: url('https://iili.io/qao6Jbs.png') !important; }
  #top-settings-holder > .drawer:nth-of-type(10) .drawer-toggle { background-image: url('https://iili.io/qaznVyB.png') !important; }
  #top-settings-holder > .drawer:nth-of-type(11) .drawer-toggle { background-image: url('https://iili.io/qao6Jbs.png') !important; }
  #top-settings-holder > .drawer:nth-of-type(12) .drawer-toggle { background-image: url('https://iili.io/qaznVyB.png') !important; }

  /* 顶栏图标阴影  */
  #top-settings-holder .drawer-toggle {
    filter: drop-shadow(0 2px 4px var(--color4)) !important;
  }

  /* 悬停/选中时仅显示选中图标 */
  #top-settings-holder .drawer-toggle:has(.drawer-icon:hover),
  #top-settings-holder .drawer-toggle:has(.drawer-icon:not(.closedIcon)) {
    background-image: none !important;
  }

  /* 悬停和选中顶栏图标 */
  #top-settings-holder .drawer-icon:hover,
  #top-settings-holder .drawer-icon:not(.closedIcon) {
      background-image: url("https://iili.io/qazwAqF.png") !important;
      width:var(--悬停和选中顶栏图标宽度) !important;
      height: var(--悬停和选中顶栏图标高度) !important;
      background-size: contain;
      background-repeat: no-repeat;
      background-position: center calc(50% + var(--悬停和选中顶栏图标下移));
      opacity: 1 !important;
  }

/* 🐤聊天区域 */
  /* 去聊天背景颜色 聊天居中*/
  #chat {
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    box-shadow: none !important;
    /* 居中 */
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    background-color: transparent;
  }

  /* 消息顶部留空 */
  .mes {
    top: var(--消息顶部留空);
    position: relative !important;
  }

  /* 消息留空 */
  .mes + .mes {
    margin-top: var(--消息留空);
  }

  /* 气泡 */
  .mes {
    align-self: center !important;
    display: flex !important;
    padding-top: var(--气泡上边距) !important;
    padding-bottom: var(--气泡下边距) !important;
    padding-left: var(--气泡左边距) !important;
    padding-right: var(--气泡右边距) !important;
    flex-direction: column !important;
    overflow: visible !important; /* 允许溢出 */
  }

  /* 气泡 */
  .mes {
    background-image: url("https://iili.io/qa5lg3b.png"), linear-gradient(
      to bottom,
      var(--color3) 0,
      var(--color3) var(--气泡上边框),
      var(--color5) var(--气泡上边框),
      var(--color3) calc(100% - var(--气泡下边框)),
      var(--color3) 100%
    );
    background-repeat: repeat, no-repeat;
    background-position: bottom left, 0 0;
    background-size: var(--格纹大小), auto;
    width: 98%;
    border-radius: 20px !important;
    box-shadow: 0 0 5px var(--color4), 0 0 10px var(--color4) !important;
    border: none !important;
  }

  .mes_block {
      position: static !important; /* 定位 */
      background-color: var(--color6) !important; 
      border-radius: 20px !important; 
      border: none 
 !important; 
      overflow: visible !important; /* 允许溢出 */
      transform: none !important; 
      perspective: none !important;
      filter: none !important;
      backdrop-filter: none !important;
      contain: none !important;
box-shadow: 0 0 5px var(--color4), 0 0 10px var(--color4) !important;
  }

  /* 顶部装饰*/
  .mes::before {
      content: "";
      position: absolute !important;
      left: 0;
      top: var(--顶部装饰上下);
      width: 100%;
      height: var(--顶部装饰高度);
      background-image: url("https://iili.io/qajFmGt.png");
      background-repeat: repeat-x;
      background-position: left top;
      background-size: auto var(--顶部装饰高度);
      clip-path: inset(0 round 20px 20px 0 0);
      pointer-events: none;
  }

  /* 底部装饰 */
  .mes::after {
      content: "";
      position: absolute !important;
      background-image: url("https://iili.io/qcM3y7e.png");
      background-size: contain;
      background-repeat: no-repeat;
      background-position: center;
      width: var(--底部装饰宽度); 
      height: var(--底部装饰高度);
      bottom: var(--底部装饰上下);
      left: var(--底部装饰左右);
      pointer-events: none;
  }

  /* 🌵头像区域 */
  /* 头像区域整体 */
  .mesAvatarWrapper {
    position: absolute !important;
    top: var(--头像区域整体上下) !important;
    left: var(--头像区域整体左右) !important;
    right: 0 !important;
    width: 100% !important;
    margin: 0 !important;
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-start !important;
    flex-wrap: nowrap !important;
    height: auto !important;
  }

  /* 头像 */
   .mesAvatarWrapper .avatar {
    position: absolute !important;
    top: var(--头像上下) !important;
    left: var(--头像左右) !important;
      transform: translateX(-50%); 
    border-radius: 0 !important;
    border: 0px !important;
    width: var(--头像宽度) !important;
    height: var(--头像高度) !important;
    overflow: visible !important;
    display: flex !important;
    justify-content: center !important;
    align-items: center !important;
    opacity: 1 !important;
filter: grayscale(0%) !important;
  }

  /* 头像图片 */
   .mesAvatarWrapper .avatar img {
    border: 0px !important;
    border-radius: 20px !important;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    object-position: var(--头像图片位置) !important;
  }

  /* 头像框 */
  .mesAvatarWrapper .avatar::before {
    content: '' !important;
    display: block !important;
    position: absolute !important;
    top: var(--头像框上下) !important;
    left: var(--头像框左右) !important;
      transform: translateX(-50%); 
    width: var(--头像框宽度) !important;
    height: var(--头像框高度) !important;
    background: url(https://iili.io/qcXS7ee.png) no-repeat center/contain !important;
    pointer-events: none !important;
  }

  /* 楼层 */
  .mesAvatarWrapper .mesIDDisplay {
    position: absolute !important;
    top: var(--楼层上下) !important;
    left: var(--楼层左右) !important;
color:var(--color7) !important;
    right: auto !important;
    box-sizing: border-box !important;
    padding: 0 !important;
    text-shadow: none !important;
    background: transparent !important;
    margin: 0 !important;
    line-height: 1 !important;
    font-weight: normal !important;
    opacity: 1 !important;
    text-align: center !important;
width:var(--楼层宽度);
    white-space: nowrap !important;
    font-size: var(--楼层字体大小) !important;
  }

  /* 时间 */
  .mesAvatarWrapper .mes_timer {
    position: absolute !important;
    top: var(--时间上下) !important;
    left: var(--时间左右) !important;
color:var(--color7) !important;
    width: var(--时间宽度) !important;
    box-sizing: border-box !important;
    text-shadow: none !important;
    margin: 0 !important;
    padding: 0 !important;
    line-height: 1 !important;
    font-weight: normal !important;
    opacity: 1 !important;
    text-align: right !important;
    white-space: nowrap !important;
    font-size: var(--时间字体大小) !important;
  }

  /* Token */
  .mesAvatarWrapper .tokenCounterDisplay {
    position: absolute !important;
color:var(--color7) !important;
    top: var(--Token上下) !important;
    left: var(--Token左右) !important;
    width: var(--Token宽度) !important;
    box-sizing: border-box !important;
    text-shadow: none !important;
    margin: 0 !important;
    padding: 0 !important;
    line-height: 1 !important;
    font-weight: normal !important;
    opacity: 1 !important;
    text-align: right !important;
    white-space: nowrap !important;
    font-size: var(--Token字体大小) !important;
    /* 可选 */
    transform: rotate(-11deg) !important;
  }

  /* 🕊️名字和时间戳 */
  /* 名字和时间戳（一般来说别动） */
  .mes .ch_name.flex-container {
    position: absolute !important;
    top: 0px !important;
    left: 0px !important;
    right: 0 !important;
    width: 100% !important;
    margin: 0 !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
  }

  /* 名字 */
  .mes .ch_name.flex-container .name_text {
    text-shadow: none !important;
    font-weight: normal !important;
    color: var(--color7) !important;
    font-style: normal !important;
    text-decoration: none !important;
    letter-spacing: normal !important;
    font-size: var(--名字字体大小) !important;
    position: absolute !important;
    top: var(--名字上下) !important;
    left: 50% !important;
    margin: 0 !important;
    padding: 0 8px 0 0 !important;
    display: inline-block !important;
    height: auto !important;
    opacity: 1 !important;
    white-space: nowrap !important;
    text-align: left !important;
